import numpy as np


class AdaptivePatternCreditDE:
    """
    Mixed-variable (1+lambda)/DE hybrid with:
      - stratified LHS initial design evaluated in batches,
      - rank-weighted elite recombination and current-to-best DE moves,
      - heavy-tailed continuous mutation with a generation-level 1/5 rule,
      - per-variable integer credit with fast forgetting and a floor,
      - type-aware integer moves (binary flip, ordinal +-1, categorical resample),
      - archive-based duplicate filtering,
      - IPOP-style population growth with elite-centroid / random restarts,
      - adaptive-step pattern search on the incumbent (expand on success,
        contract on failure) that replaces the fixed one-shot scan.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        dim = self.dim
        budget = self.budget
        rng = np.random.default_rng()

        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        span = ub - lb
        vt = list(func.variable_types)

        is_int = np.array([v != "continuous" for v in vt], dtype=bool)
        is_bin = np.array([v == "binary" for v in vt], dtype=bool)
        is_ord = np.array([v == "ordinal" for v in vt], dtype=bool)

        nv = np.ones(dim, dtype=int)
        for i in range(dim):
            if is_int[i]:
                nv[i] = 2 if is_bin[i] else max(1, int(round(func.n_values[i])))

        cont_idx = np.where(~is_int)[0]
        int_idx = np.where(is_int)[0]
        n_cont = len(cont_idx)
        int_mut = np.array([j for j in int_idx if nv[j] >= 2], dtype=int)
        n_mut = len(int_mut)
        w_int = np.ones(n_mut)

        # ---------- helpers ----------
        def clip(X):
            X = np.atleast_2d(X).copy()
            if n_cont:
                X[:, cont_idx] = np.clip(X[:, cont_idx], lb[cont_idx], ub[cont_idx])
            if len(int_idx):
                X[:, int_idx] = np.clip(np.rint(X[:, int_idx]), 0, nv[int_idx] - 1)
            return X

        def sample_random(n):
            X = np.empty((n, dim))
            if n_cont:
                if n > 1:
                    for j in cont_idx:
                        u = (rng.permutation(n) + rng.random(n)) / n
                        X[:, j] = lb[j] + u * span[j]
                else:
                    X[:, cont_idx] = lb[cont_idx] + rng.random((n, n_cont)) * span[cont_idx]
            for j in int_idx:
                X[:, j] = rng.integers(0, nv[j], size=n)
            return X

        def key(x):
            return tuple(np.round(x, 9))

        # ---------- state ----------
        evals = 0
        seen = set()
        arch_X, arch_Y = [], []
        g_x, g_y = None, np.inf

        def evaluate_batch(X):
            nonlocal evals, g_x, g_y
            remaining = budget - evals
            if remaining <= 0 or len(X) == 0:
                return np.empty(0)
            X = np.asarray(X)[:remaining]
            ys = np.asarray(func(X), dtype=float).reshape(-1)
            for x, y in zip(X, ys):
                evals += 1
                seen.add(key(x))
                arch_X.append(x.copy())
                arch_Y.append(float(y))
                if y < g_y:
                    g_y = float(y)
                    g_x = x.copy()
            return ys

        def elites(k=5):
            if not arch_Y:
                return []
            order = np.argsort(arch_Y)[:k]
            return [arch_X[i] for i in order]

        def elite_pool_for_de(k=20):
            if len(arch_Y) < 3:
                return None
            order = np.argsort(arch_Y)[:min(k, len(arch_Y))]
            return np.array([arch_X[i] for i in order])

        def elite_centroid(k=5):
            pool = elites(k)
            if not pool:
                return None
            w = 1.0 / np.arange(1, len(pool) + 1)
            w = w / w.sum()
            return np.sum([wi * p for wi, p in zip(w, pool)], axis=0)

        def int_move(child, j):
            if is_bin[j]:
                child[j] = 1.0 - child[j]
            elif is_ord[j] and rng.random() < 0.7:
                step = 1.0 if rng.random() < 0.5 else -1.0
                new = child[j] + step
                if new < 0 or new > nv[j] - 1:
                    new = child[j] - step
                child[j] = new
            else:
                new = int(rng.integers(0, nv[j] - 1))
                if new >= child[j]:
                    new += 1
                child[j] = new

        def make_children(parent, sigma, m, pool, de_pool, best_x):
            C = np.repeat(parent[None, :], m, axis=0)
            changes = []
            if n_mut:
                pw = w_int + 0.1
                p_credit = pw / pw.sum()
            if len(pool) >= 2:
                rw = 1.0 / np.arange(1, len(pool) + 1)
                rw = rw / rw.sum()
            for k in range(m):
                c = C[k]
                if len(pool) >= 2 and rng.random() < 0.25:
                    other = pool[rng.choice(len(pool), p=rw)]
                    mask = rng.random(dim) < 0.5
                    c[:] = np.where(mask, c, other)
                if n_cont:
                    u = rng.random()
                    if de_pool is not None and u < 0.35:
                        a, b = rng.choice(len(de_pool), size=2, replace=False)
                        F = rng.uniform(0.4, 0.9)
                        diff_ab = de_pool[a][cont_idx] - de_pool[b][cont_idx]
                        if rng.random() < 0.5 and best_x is not None:
                            move = F * (best_x[cont_idx] - c[cont_idx]) + F * diff_ab
                        else:
                            move = F * diff_ab
                        c[cont_idx] = c[cont_idx] + move
                        c[cont_idx] += 0.05 * sigma * rng.standard_normal(n_cont) * span[cont_idx]
                    else:
                        s = sigma * np.exp(0.3 * rng.standard_normal())
                        mask_c = rng.random(n_cont) < 0.6
                        if not mask_c.any():
                            mask_c[rng.integers(0, n_cont)] = True
                        if rng.random() < 0.1:
                            noise = np.clip(rng.standard_cauchy(n_cont), -5, 5)
                        else:
                            noise = rng.standard_normal(n_cont)
                        c[cont_idx] = c[cont_idx] + mask_c * noise * s * span[cont_idx]
                ch = []
                if n_mut:
                    nm = min(n_mut, max(1, int(rng.poisson(max(0.5, 0.2 * n_mut)))))
                    sel = rng.choice(n_mut, size=nm, replace=False, p=p_credit)
                    for s_ in sel:
                        int_move(c, int_mut[s_])
                        ch.append(int(s_))
                changes.append(ch)
            return clip(C), changes

        def gather(parent, sigma, m, pool, de_pool, best_x):
            cand_X, cand_ch, local = [], [], set()
            tries = 0
            while len(cand_X) < m and tries < 4:
                sg = sigma if tries == 0 else max(sigma, 0.1)
                C, chs = make_children(parent, sg, m, pool, de_pool, best_x)
                for x, ch in zip(C, chs):
                    kx = key(x)
                    if kx in seen or kx in local:
                        continue
                    local.add(kx)
                    cand_X.append(x)
                    cand_ch.append(ch)
                    if len(cand_X) >= m:
                        break
                tries += 1
            if not cand_X:
                cand_X = [sample_random(1)[0]]
                cand_ch = [[]]
            return np.array(cand_X), cand_ch

        def pattern_candidates(x, step):
            """Coordinate probes on continuous vars and integer neighbours."""
            cands = []
            for j in int_mut:
                for v in range(nv[j]):
                    if v != int(x[j]):
                        c = x.copy()
                        c[j] = v
                        cands.append(c)
            for j in cont_idx:
                for d in (-step, step):
                    c = x.copy()
                    c[j] = np.clip(c[j] + d * span[j], lb[j], ub[j])
                    cands.append(c)
            out, local = [], set()
            for c in cands:
                kc = key(c)
                if kc not in seen and kc not in local:
                    local.add(kc)
                    out.append(c)
            return np.array(out) if out else np.empty((0, dim))

        # ---------- initial design ----------
        lam_base = 4 + int(3 * np.log(max(dim, 2)))
        lam_max = 64
        n_init = min(budget, max(10, min(budget // 5, 8 * dim)))
        X0 = sample_random(n_init)
        evaluate_batch(X0)

        lam = lam_base
        sigma = 0.25
        stall = 0
        stall_limit = 12 + 4 * dim
        pat_step = 0.05          # adaptive pattern step (fraction of span)
        probed = False
        loc_x, loc_y = None, np.inf
        if arch_Y:
            i0 = int(np.argmin(arch_Y))
            loc_x, loc_y = arch_X[i0].copy(), arch_Y[i0]

        # ---------- main loop ----------
        while evals < budget:
            if loc_x is None or stall > stall_limit or sigma < 1e-4:
                if loc_x is not None and stall > stall_limit:
                    lam = min(lam * 2, lam_max)
                else:
                    lam = lam_base
                pool = elites(5)
                r = rng.random()
                if pool and r < 0.3:
                    # restart from elite centroid with small perturbation
                    x = elite_centroid(5).copy()
                    if n_cont:
                        msk = rng.random(n_cont) < 0.5
                        x[cont_idx] = x[cont_idx] + msk * rng.standard_normal(n_cont) * 0.05 * span[cont_idx]
                    if n_mut:
                        int_move(x, int_mut[rng.integers(0, n_mut)])
                    x = clip(x)[0]
                    if key(x) in seen:
                        x = sample_random(1)[0]
                    ys = evaluate_batch(x[None, :])
                    cand_x = x
                    cand_y = float(ys[0]) if len(ys) else np.inf
                elif pool and r < 0.6:
                    base = pool[rng.integers(0, len(pool))]
                    x = base.copy()
                    if n_cont:
                        msk = rng.random(n_cont) < 0.5
                        x[cont_idx] = x[cont_idx] + msk * rng.standard_normal(n_cont) * 0.1 * span[cont_idx]
                    if n_mut:
                        int_move(x, int_mut[rng.integers(0, n_mut)])
                    x = clip(x)[0]
                    if key(x) in seen:
                        x = sample_random(1)[0]
                    ys = evaluate_batch(x[None, :])
                    cand_x = x
                    cand_y = float(ys[0]) if len(ys) else np.inf
                else:
                    Xr = sample_random(max(8, lam))
                    keep, local = [], set()
                    for i, x in enumerate(Xr):
                        kx = key(x)
                        if kx not in seen and kx not in local:
                            local.add(kx)
                            keep.append(i)
                    Xr = Xr[keep] if keep else sample_random(1)
                    ys = evaluate_batch(Xr)
                    if len(ys) == 0:
                        break
                    k = int(np.argmin(ys))
                    cand_x, cand_y = Xr[k], float(ys[k])
                loc_x, loc_y = cand_x.copy(), cand_y
                sigma = 0.25 if rng.random() < 0.5 else 0.35
                pat_step = 0.05
                stall = 0
                probed = False
                continue

            # adaptive-step pattern search on the incumbent, once per stall cycle
            if not probed and stall >= stall_limit // 2:
                probed = True
                N = pattern_candidates(loc_x, pat_step)
                if len(N) and evals < budget:
                    ys = evaluate_batch(N)
                    if len(ys):
                        k = int(np.argmin(ys))
                        if ys[k] < loc_y:
                            old_x = loc_x.copy()
                            loc_x, loc_y = N[k].copy(), float(ys[k])
                            pat_step = min(pat_step * 1.5, 0.3)
                            # directional extrapolation along the successful move
                            if evals < budget:
                                ext = clip(loc_x + (loc_x - old_x))[0]
                                if key(ext) not in seen:
                                    ye = evaluate_batch(ext[None, :])
                                    if len(ye) and ye[0] < loc_y:
                                        loc_x, loc_y = ext.copy(), float(ye[0])
                            stall = 0
                            probed = False
                        else:
                            pat_step = max(pat_step * 0.5, 1e-4)
                continue

            m = min(lam, budget - evals)
            if m <= 0:
                break
            pool = elites(5)
            de_pool = elite_pool_for_de(20)
            C, chs = gather(loc_x, sigma, m, pool, de_pool, g_x)
            ys = evaluate_batch(C)
            if len(ys) == 0:
                break

            improved = ys < loc_y
            if n_mut:
                w_int *= 0.9
                for i in np.where(improved)[0]:
                    if i < len(chs):
                        for s_ in chs[i]:
                            w_int[s_] += 1.0
                w_int = np.clip(w_int, 0.05, 30.0)

            succ = float(np.mean(improved))
            k = int(np.argmin(ys))
            if ys[k] < loc_y:
                loc_x, loc_y = C[k].copy(), float(ys[k])
                stall = 0
                probed = False
            else:
                stall += 1

            sigma = float(np.clip(sigma * np.exp(0.5 * (succ - 0.2)), 1e-5, 0.5))

        return g_y, g_x
